const d = $input.first().json;
const rounds = d.rounds || [];
let summary = '';
rounds.forEach(r => {
  const c = r.candidates || [];
  summary += `Round ${r.round}: ` + c.map(x => x.title + ' (' + x.score + ')').join(' | ') + '\n';
});

return {
  idea: d.idea,
  category: d.category,
  best_title: d.best_title,
  best_score: d.best_score,
  rounds_summary: summary,
  full_result: d
};

